#!/usr/bin/env python3
"""
Extract dominant colors from a logo image.

Filters out whites, blacks, and transparent pixels, then uses color
quantization to group similar shades. Returns the INPUT IMAGE unchanged
(pass-through for pipelines) plus color data in the output JSON metadata.

Params:
  num_colors     - Number of colors to extract (default: 4)
"""
import sys
import json
import base64
import io
import math
from collections import Counter
from PIL import Image
from script_io import read_input, write_output, write_error


def color_distance(c1, c2):
    return math.sqrt((c1[0]-c2[0])**2 + (c1[1]-c2[1])**2 + (c1[2]-c2[2])**2)


def quantize_color(color, bucket=32):
    r, g, b = color
    return ((r // bucket) * bucket, (g // bucket) * bucket, (b // bucket) * bucket)


def luminance(color):
    r, g, b = color
    return 0.299 * r + 0.587 * g + 0.114 * b


def get_dominant_colors(img, num_colors=4):
    # Downsample for performance - color extraction does not need full res
    analysis = img.copy()
    MAX_DIM = 256
    if analysis.width > MAX_DIM or analysis.height > MAX_DIM:
        analysis.thumbnail((MAX_DIM, MAX_DIM), Image.LANCZOS)

    if analysis.mode != 'RGBA':
        analysis = analysis.convert('RGBA')

    pixels = analysis.load()
    all_colors = []
    color_to_q = {}

    WHITE_THRESH = 235
    BLACK_THRESH = 30

    for y in range(analysis.height):
        for x in range(analysis.width):
            r, g, b, a = pixels[x, y]
            if a < 200:
                continue
            if r > WHITE_THRESH and g > WHITE_THRESH and b > WHITE_THRESH:
                continue
            if r < BLACK_THRESH and g < BLACK_THRESH and b < BLACK_THRESH:
                continue

            actual = (r, g, b)
            q = quantize_color(actual)
            all_colors.append(actual)
            color_to_q[actual] = q

    if not all_colors:
        return [(128, 128, 128)]

    groups = {}
    for c in all_colors:
        q = color_to_q[c]
        if q not in groups:
            groups[q] = []
        groups[q].append(c)

    reps = []
    for q, actuals in groups.items():
        counts = Counter(actuals)
        best = counts.most_common(1)[0][0]
        reps.append((best, len(actuals), q))

    reps.sort(key=lambda x: x[1], reverse=True)

    MIN_DIST = 60
    result = []
    for actual, count, q in reps:
        distinct = True
        for existing in result:
            eq = color_to_q.get(existing, existing)
            if color_distance(q, eq) < MIN_DIST:
                distinct = False
                break
        if distinct:
            result.append(actual)
        if len(result) >= num_colors:
            break

    return result if result else [(128, 128, 128)]


def main():
    input_bytes, content_type, params = read_input()
    if not input_bytes:
        write_error("no input image provided")
        return

    img = Image.open(io.BytesIO(input_bytes))

    num_colors = int(params.get("num_colors", "4"))

    colors = get_dominant_colors(img, num_colors)
    colors.sort(key=luminance)

    # Pass through the original input image unchanged
    buf = io.BytesIO()
    fmt = "PNG"
    ct = content_type or "image/png"
    if ct == "image/jpeg":
        fmt = "JPEG"
        if img.mode == "RGBA":
            img = img.convert("RGB")
    img.save(buf, format=fmt)

    colors_data = []
    for c in colors:
        colors_data.append({
            "rgb": list(c),
            "hex": "#{:02x}{:02x}{:02x}".format(c[0], c[1], c[2]),
            "luminance": round(luminance(c), 1),
        })

    write_output(buf.getvalue(), ct, colors=colors_data)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Convert an image to a different format (PNG, JPEG, WebP, BMP, HEIC).

iPhone HEIC files (10-bit HDR / Display P3) are decoded via pillow_heif's
open_heif() so tone-mapping to 8-bit sRGB is applied — otherwise the
output gets crushed to near-black. Other formats use PIL as usual.

Params:
    format   – target format: png, jpeg, webp, bmp, heic (default: webp)
    quality  – compression quality 1-100 for lossy formats (default: 85)
    max_size – cap long edge at N pixels (default: 2048; 0 = no resize)
"""

import io
from PIL import Image
import pillow_heif
from script_io import read_input, write_output, write_error

PARAM_DEFS = [
    {"name": "format", "description": "Target format", "default_value": "webp",
     "allowed_values": ["png", "jpeg", "webp", "bmp", "heic"]},
    {"name": "quality", "description": "Compression quality 1-100 for lossy formats",
     "default_value": "85"},
    {"name": "max_size", "description": "Max long edge in pixels (0 = no resize)",
     "default_value": "2048"},
]

HEIF_BRANDS = (b"heic", b"heix", b"hevc", b"hevx", b"heim", b"heis",
               b"hevm", b"hevs", b"mif1", b"msf1")

def _is_heif(data: bytes) -> bool:
    return len(data) >= 12 and data[4:8] == b"ftyp" and data[8:12] in HEIF_BRANDS

def _resize(img: Image.Image, max_edge: int) -> Image.Image:
    if max_edge <= 0:
        return img
    w, h = img.size
    if max(w, h) <= max_edge:
        return img
    if w >= h:
        new_w, new_h = max_edge, max(1, h * max_edge // w)
    else:
        new_w, new_h = max(1, w * max_edge // h), max_edge
    return img.resize((new_w, new_h), Image.LANCZOS)

def main():
    input_bytes, content_type, params = read_input()
    if not input_bytes:
        write_error("no input image provided")
        return

    fmt = params.get("format", "webp").lower().strip()
    try:
        quality = max(1, min(100, int(params.get("quality", "85"))))
    except ValueError:
        write_error("quality must be a number between 1 and 100")
        return
    try:
        max_size = int(params.get("max_size", "2048"))
        max_size = max(0, max_size)
    except ValueError:
        max_size = 2048

    fmt_map = {
        "png":  ("PNG",  "image/png"),
        "jpeg": ("JPEG", "image/jpeg"),
        "webp": ("WEBP", "image/webp"),
        "bmp":  ("BMP",  "image/bmp"),
        "heic": ("HEIF", "image/heic"),  # HEIF supports alpha → skips flatten
    }

    if fmt not in fmt_map:
        write_error(f"Unsupported format '{fmt}'. Use: png, jpeg, webp, bmp, heic")
        return

    pil_fmt, mime = fmt_map[fmt]

    try:
        # HEIC: decode via pillow_heif.open_heif so HDR→8bit tone mapping
        # is applied. The PIL-plugin path skips that and produces crushed
        # blacks for iPhone HDR shots.
        if _is_heif(input_bytes):
            heif = pillow_heif.open_heif(io.BytesIO(input_bytes), convert_hdr_to_8bit=True)
            img = heif.to_pillow()
        else:
            img = Image.open(io.BytesIO(input_bytes))

        img = _resize(img, max_size)

        # JPEG/BMP don't support alpha — flatten onto white
        if pil_fmt in ("JPEG", "BMP") and img.mode in ("RGBA", "LA", "PA"):
            bg = Image.new("RGB", img.size, (255, 255, 255))
            if img.mode == "RGBA":
                bg.paste(img, mask=img.split()[-1])
            else:
                bg.paste(img, mask=img.convert("RGBA").split()[-1])
            img = bg
        elif pil_fmt in ("JPEG", "BMP") and img.mode != "RGB":
            img = img.convert("RGB")

        buf = io.BytesIO()
        save_kwargs = {}
        if pil_fmt in ("JPEG", "WEBP", "HEIF"):
            save_kwargs["quality"] = quality
        if pil_fmt == "PNG":
            save_kwargs["optimize"] = True

        img.save(buf, format=pil_fmt, **save_kwargs)
        write_output(buf.getvalue(), mime)

    except Exception as e:
        write_error(f"Failed to convert image: {str(e)}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Extract metadata from an image: dimensions, format, mode, file size, DPI, EXIF.

Returns JSON via the text response_type (no image output).
"""

import io
from PIL import Image
from PIL.ExifTags import TAGS
from script_io import read_input, write_output, write_error


def main():
    input_bytes, content_type, params = read_input()
    if not input_bytes:
        write_error("no input image provided")
        return

    try:
        img = Image.open(io.BytesIO(input_bytes))

        meta = {
            "width": img.width,
            "height": img.height,
            "format": img.format or "unknown",
            "mode": img.mode,
            "has_alpha": img.mode in ("RGBA", "LA", "PA"),
            "file_size_bytes": len(input_bytes),
            "megapixels": round(img.width * img.height / 1_000_000, 2),
        }

        # DPI / resolution
        dpi = img.info.get("dpi")
        if dpi:
            meta["dpi_x"] = round(dpi[0])
            meta["dpi_y"] = round(dpi[1])

        # Animation frames
        try:
            meta["frames"] = getattr(img, "n_frames", 1)
            meta["is_animated"] = getattr(img, "is_animated", False)
        except Exception:
            pass

        # EXIF data (best effort)
        exif = {}
        try:
            raw_exif = img.getexif()
            if raw_exif:
                for tag_id, value in raw_exif.items():
                    tag = TAGS.get(tag_id, str(tag_id))
                    # Skip binary/bytes fields and convert non-serializable types
                    if isinstance(value, bytes):
                        continue
                    elif isinstance(value, (list, tuple)):
                        # Handle sequences that might contain non-serializable items
                        try:
                            exif[tag] = list(value)
                        except (TypeError, ValueError):
                            exif[tag] = str(value)
                    elif isinstance(value, (str, int, float, bool)) or value is None:
                        exif[tag] = value
                    else:
                        exif[tag] = str(value)
        except Exception:
            pass
        if exif:
            meta["exif"] = exif

        # Return as text response
        write_output(b"", "text/plain", text=meta)

    except Exception as e:
        write_error(f"failed to extract metadata: {str(e)}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Convert an SVG image to PNG.

Params:
    width - output width in pixels; aspect ratio is preserved if height is omitted (default: original SVG size)
    height - output height in pixels (default: derived from width or original)
    scale - scale factor applied when width/height are not set (default: 1)
"""

import io
from script_io import read_input, write_output, write_error

try:
    import cairosvg
except ImportError:
    write_error("cairosvg is not installed")
    exit(1)

PARAM_DEFS = [
    {"name": "width", "description": "Output width in pixels", "default_value": ""},
    {"name": "height", "description": "Output height in pixels", "default_value": ""},
    {"name": "scale", "description": "Scale factor when width/height not set", "default_value": "1"},
]


def main():
    input_bytes, content_type, params = read_input()

    if not input_bytes:
        write_error("no SVG input provided")
        return

    width = params.get("width", "").strip()
    height = params.get("height", "").strip()
    scale = params.get("scale", "1").strip()

    try:
        width = int(width) if width else None
        height = int(height) if height else None
        scale = float(scale) if scale else 1.0
    except ValueError as e:
        write_error(f"invalid parameter value: {e}")
        return

    kwargs = {}
    if width:
        kwargs["output_width"] = width
    if height:
        kwargs["output_height"] = height
    if not width and not height and scale != 1.0:
        kwargs["scale"] = scale

    try:
        png_bytes = cairosvg.svg2png(bytestring=input_bytes, **kwargs)
        write_output(png_bytes, "image/png")
    except Exception as e:
        write_error(f"SVG conversion failed: {e}")


if __name__ == "__main__":
    main()
